// Generated by scripts/vendor_cluster_flow.py from PhysicsEngine apps/cosmic/control_help.hpp:
// the lab's tooltip text, without its ImGui widget wrappers.
#pragma once
#include <string_view>
#include <utility>

namespace cosmic_ui {
inline char const* help(std::string_view label) {
    static constexpr std::pair<std::string_view,char const*> entries[]={
        {"##uiscale","Resize text, controls, and the sidebar. Saved beside the application. This does not change the simulation or exported image resolution."},
        {"Pause","Pause live physics while keeping the camera and appearance controls available. Space also toggles playback."},
        {"Resume","Continue the current simulation from its paused state. Space also toggles playback."},
        {"Play replay","Play the saved frames at the playback FPS. No physics is recomputed; camera and appearance remain adjustable."},
        {"Pause replay","Pause on the current cached frame so you can inspect it or change the camera."},
        {"Restart","Recreate the initial state with the current Scene settings and seed. The current unsaved live evolution is replaced."},
        {"To start","Pause replay and return to its first saved frame. This does not rerun physics."},
        {"View","Appearance and image export. These controls do not change the simulated dynamics."},
        {"Physics","Live dynamics and numerical accuracy. Gas grid is in Scene; timestep and transport settings are here."},
        {"Scene","Model, volume, resolution, and initial conditions. Apply and restart, or bake from start, to use changes."},
        {"Bake","Compute a recording once, then replay, inspect, or export it without rerunning the simulation."},
        {"##view","Choose the color field: gas density, speed, temperature proxy, or compression. Compression highlights converging flow, not a measured shock Mach number."},
        {"Exposure","Increase or decrease the displayed brightness. Changes only the image, not density, temperature, or dynamics."},
        {"Flow tracers","Show massless markers carried by the gas velocity. They illustrate flow but do not source gravity or change the gas. Hidden automatically in compression mode."},
        {"Tracer brightness","Adjust marker brightness without changing their number, gas density, or physical accuracy."},
        {"Slice thickness","Show a slab along the box Z axis. 1 shows the full depth; smaller values reveal interior structure. Hidden gas still evolves normally."},
        {"Slice position","Move the displayed slab along Z, from -1 at one box face to +1 at the other. This only changes visibility."},
        {"##samples","Ray samples per pixel through the volume. More samples reduce rendering artifacts at a GPU cost; they do not improve simulated gas or gravity resolution."},
        {"Save image...","Save the current scene as a PNG without the control panel. Uses the visible scene viewport resolution."},
        {"Reset camera","Stop automatic rotation, restore default angles and rotation speeds, recenter on the whole box, and restore the default zoom. Simulation state and appearance settings are retained."},
        {"Camera motion","Set the two orbit angles and independent automatic rotation speeds around the current focus. Works live, during replay, and in MP4 exports. Camera motion is independent of simulation time."},
        {"Horizontal angle (degrees)","Yaw around the vertical axis, in degrees. Editing this angle turns off horizontal automatic rotation so you can set a starting view. Enable Rotate horizontally to continue from this angle."},
        {"Horizontal speed (deg/s)","Horizontal rotation speed in degrees per real second, or per video second when exporting. Negative values reverse direction; zero holds the angle. Takes effect when Rotate horizontally is enabled."},
        {"Rotate horizontally","Continuously change the horizontal angle at the selected speed, wrapping through full turns. Independent of vertical motion. Continues while physics or replay is paused. Manual orbit dragging stops both axes."},
        {"Vertical angle (degrees)","Vertical orbit angle, in degrees. Supports complete turns over the poles, including upside-down views. Editing it stops vertical automatic rotation. Enable Rotate vertically to continue from this angle."},
        {"Vertical speed (deg/s)","Vertical rotation speed in degrees per real second, or per video second when exporting. Negative values reverse direction. Full rotations continue smoothly through the poles; the view can become inverted."},
        {"Rotate vertically","Continuously change the vertical orbit angle at the selected speed. Independent of horizontal motion. Continues while physics or replay is paused. Manual orbit dragging stops both axes."},
        {"Stop camera motion","Disable both automatic rotations at their current angles. Keeps the current focus, zoom, and configured speeds."},
        {"Explore volume","Show camera focus and distance controls. Left drag orbits around the focus; right/middle drag or Shift + left drag pans it. Scroll to zoom, including inside the volume. Works during live simulation and replay."},
        {"Camera distance","Distance from the camera to its focus in normalized box coordinates. Smaller values zoom in; you can enter the volume. Finer gas cells and cache resolution are needed to reveal more physical detail."},
        {"Focus X","Move the orbit center along X: -1 and +1 are the two box faces. Pan or adjust focus before zooming to explore another region. Does not change physics."},
        {"Focus Y","Move the orbit center along Y: -1 and +1 are the two box faces. Pan or adjust focus before zooming to explore another region. Does not change physics."},
        {"Focus Z","Move the orbit center along Z: -1 and +1 are the two box faces. Useful for reaching deeper regions. Does not change physics."},
        {"Evolution pace","Requested simulation time per real second, limited by compute speed. Does not set timestep accuracy. Baking ignores this pacing limit."},
        {"Dark halo gravity","Multiply the fixed analytic halo acceleration in Cluster flow. This changes force strength, not accuracy. Gas grid samples the field; smaller timesteps resolve its effect better."},
        {"Cooling rate","How quickly cluster gas loses internal energy toward the cooling floor. Higher values cool faster. Disabled in Cosmological volume."},
        {"Cooling temperature floor","Target pressure/density for cluster cooling, in code units. Gas above this value cools toward it; it is not a Kelvin temperature or a resolution setting."},
        {"Outbursts","Expand controls for energy and momentum injected around the two central cluster halos. Disabled in Cosmological volume."},
        {"Automatic outbursts","Trigger repeated cluster outbursts at the chosen interval while time advances. Turning this off still allows manual outbursts."},
        {"Outflow strength","Overall multiplier for injected heating and velocity kicks. Zero disables injection. Stronger bursts may require smaller timesteps."},
        {"Interval","Simulation time between automatic outbursts, in cluster code units. This is independent of real-time playback speed."},
        {"Injection radius","Characteristic outburst radius in cluster code units. The region extends to about 2.26 times this radius. Use a gas cell size smaller than the radius to resolve it."},
        {"Heating","Thermal energy added per unit gas mass by an outburst, before its spatial shape and strength multiplier. Raises pressure and drives expansion."},
        {"Velocity kick","Radial velocity impulse from an outburst, before its spatial shape and strength multiplier. Higher values produce faster outflow."},
        {"Jet collimation","Zero gives spherical injection; one concentrates it toward the jet axis. Changes the outburst shape, not numerical accuracy."},
        {"Trigger outburst","Inject one outburst immediately, including while paused. Resume to follow the resulting flow."},
        {"Timestep & solver","Numerical accuracy controls. Combine second-order transport and smaller timesteps with a fine gas grid. They cannot add physics absent from the chosen model."},
        {"##accuracy","Fast uses more diffusive first-order transport. Balanced uses second order. Accurate and Fine timesteps reduce the Courant limit and maximum timestep, increasing compute time. Manual changes select Custom."},
        {"Second-order transport","Use slope-limited spatial reconstruction and two-stage time integration for gas transport. Usually preserves filaments and shocks better than first order. Gravity and other source terms remain approximate."},
        {"Courant limit","Limit how far gas signals travel relative to a cell during each step. Lower values take more, smaller steps and can improve time resolution. The actual step also obeys gravity and expansion limits."},
        {"Maximum timestep","Upper bound on a solver step: cluster code time or cosmological Gyr. Lower values improve time sampling of gravity and gas changes, with more work. CFL or gravity limits may already require smaller steps."},
        {"##model","Cluster flow preserves the preformed filament network, fixed halos, cooling, and outbursts. Cosmological volume grows structure from fluctuations with expansion and live gravity; its appearance differs."},
        {"Cluster cube size (code units)","Side length of the populated periodic cluster box. Default 2 preserves the original scene. Clump count grows with volume: 2 gives 38, 4 gives 304, and 8 gives 2432. New halos and connected filaments fill the added space at roughly constant density and width. Increase Gas grid to retain detail, then apply and restart. Pan and zoom to explore different regions."},
        {"Comoving cube size (Mpc)","Cosmological side length, in comoving Mpc. Physical side length is a times this value. A larger box includes larger wavelengths but has coarser cells at the same grid. Doubling the side gives eight times the volume. Apply and restart."},
        {"H0 (km/s/Mpc)","Present expansion rate. Changes the expansion history, gravity normalization, and initial spectrum in Cosmological volume. Units are km/s per Mpc. Apply and restart."},
        {"Dark matter / Omega_dm","Present dark-matter density divided by critical density. Changes the mass of live dark-matter particles, total gravity, expansion, and initial spectrum. Particle count is controlled separately by the gravity mesh."},
        {"Baryons / Omega_b","Present baryonic density divided by critical density. Sets the mean gas density and its contribution to gravity, expansion, and the initial spectrum. This is not the visual tracer count."},
        {"Dark energy / Omega_de","Present dark-energy density divided by critical density. Affects homogeneous expansion; it is not a particle species or a local repulsive force. Curvature is derived from the density sum."},
        {"Set flat geometry","Set Omega_de = 1 - Omega_dm - Omega_b, giving zero curvature. Requires the matter sum to be at most 1 because negative dark energy is not supported. Apply and restart."},
        {"Dark energy w","Constant dark-energy equation of state. -1 is a cosmological constant. Other values change how its density evolves with expansion. This simplified model omits radiation and neutrinos."},
        {"Starting redshift","Start at scale factor a = 1/(1+z). Larger redshift starts earlier with smaller linear fluctuations. Bake duration is elapsed time after this starting point, not time since the Big Bang."},
        {"sigma8","Input linear fluctuation amplitude normalized at redshift zero on an 8/h Mpc scale. Higher values seed stronger fluctuations; zero starts homogeneous. Finite box and grid resolution limit the realized spectrum."},
        {"Spectral index ns","Tilt of the initial primordial power spectrum. Larger values favor small-scale power relative to large scales, within the finite box and mesh limits. Apply and restart."},
        {"##pm","Cosmological gravity mesh cells and live dark-matter particle count per side. A finer mesh resolves smaller gravitational structure and uses more memory/time. Gas grid independently resolves gas; smaller timesteps improve force integration. Apply and restart."},
        {"TNG-like cosmology preset","Restore the default TNG-like density and spectrum values, w, starting redshift, and 32-cubed gravity mesh. Keeps the selected box size. This remains a simplified visualization model. Apply and restart."},
        {"##grid","Number of simulated gas cells per side. A finer grid resolves narrower filaments, shocks, and pressure gradients. Cluster gravity is sampled at these cells; cosmological force resolution also depends on its gravity mesh. Doubling grid size uses eight times as many cells and usually smaller steps. Apply and restart."},
        {"##tracercount","Number of massless visual flow markers. More markers improve visual sampling only. For gas accuracy increase Gas grid, use second-order transport, and reduce timestep limits. For cosmological gravity increase Gravity mesh / DM particles; cluster halos are analytic. Apply and restart."},
        {"##seed","Reproducible random seed for the initial scene and tracer positions. Changing it creates a different realization, not a more accurate simulation. Apply and restart."},
        {"Baryonic gas density","Multiply initial cluster gas mass and density. Cluster flow has no gas self-gravity, so this does not strengthen its fixed halo forces. Cosmological gas density is instead set by Omega_b. Apply and restart."},
        {"Initial temperature","Multiply the initial cluster pressure/density, changing pressure support and sound speed. This uses code units, not Kelvin. Apply and restart."},
        {"Initial inflow","Multiply the initial gas motion along filaments toward dense knots. Zero removes this inflow but retains separately controlled velocity perturbations. Apply and restart."},
        {"Velocity perturbations","Strength of coherent transverse motions that seed asymmetric cluster flow. Zero removes these perturbations. This is an initial-condition control, not solver noise. Apply and restart."},
        {"Filament width","Multiply the original filaments' widths in cluster code units. Narrower filaments need smaller gas cells to resolve them. Volume size does not stretch these widths. Apply and restart."},
        {"Dark halo softening","Length that smooths the fixed cluster halo forces near their centers, in code units. Smaller values make forces more concentrated; they do not automatically improve accuracy. Resolve this length with the gas grid and use smaller timesteps. Apply and restart."},
        {"Initial gas temperature / 10,000 K","Initial cosmological gas temperature in multiples of 10,000 Kelvin. Subsequent pressure, shocks, gravity, and cosmic expansion change it; radiative cooling is omitted in this mode. Apply and restart."},
        {"Apply scene & restart","Apply the pending model, volume, grid, seed, and initial conditions, replacing the current live state. Saved recordings are retained."},
        {"About cosmology","Show a short explanation of the cosmological model and the physics it omits."},
        {"Cancel bake (keep frames)","Stop computation after the current solver work and keep completed frames. The partial recording can be replayed or exported."},
        {"Bake another simulation","Expand settings for a new recording. Uses the live Scene and Physics configuration, which may differ from the currently opened recording."},
        {"Evolution duration","Total cluster code time to simulate from the seeded initial state. Independent of playback speed and movie length. Longer durations require more solver work."},
        {"Evolution duration (Gyr)","Elapsed billions of years to simulate after the chosen starting redshift. Independent of playback speed and movie length. Longer durations require more solver work."},
        {"##bakeframes","Number of evenly spaced saved states, including the start and end. More frames improve animation time sampling and use more disk space. Movie length is frame count divided by movie FPS; this does not set solver timestep accuracy."},
        {"##cachegrid","Volume resolution saved in each frame, capped by Gas grid. Lower values reduce file size and replay cost but lose visual detail. The simulation still runs at the full Gas grid resolution."},
        {"##cachetracers","Maximum markers saved per frame, capped by Flow tracer count. Fewer markers reduce file size and replay cost without changing the simulated dynamics."},
        {"Bake from start...","Choose a .cflow file and simulate from the beginning using the current Scene and Physics settings, including pending changes. Runs as fast as computation allows and opens the recording when finished."},
        {"Open cache...","Open a previously saved .cflow visual recording. Does not resume a full-precision solver checkpoint. Recorded settings are shown in Scene."},
        {"##timeline","Pause and jump to a saved frame. Reads from disk without rerunning physics. Frame zero is the initial state."},
        {"Playback frames / second","Speed for viewing saved frames. Does not change their simulated time spacing or MP4 export FPS. Interactive playback may skip frames to keep up."},
        {"Loop replay","Return to the first cached frame when playback reaches the end."},
        {"Return to live","Leave cache playback and return to the live simulation. Scene controls become editable again; saved files remain on disk."},
        {"##moviequality","Pixel resolution of the MP4: 720p, 1080p, or 4K. Higher resolutions cost GPU and encoding time; they cannot restore detail missing from the cached volume."},
        {"##moviefps","Encoded movie frames per second. Every cached frame is exported once: duration = frame count / FPS. No extra states are interpolated or simulated."},
        {"Export MP4...","Render the complete cache without the UI using the current appearance and camera-motion settings. Enabled rotations start at the current angles and follow video time at the configured degrees per second. Focus, zoom, speeds, and appearance are locked during export. Requires FFmpeg on PATH."},
        {"Stop export (keep video)","Finish the video using the frames already exported. The resulting MP4 will be shorter; the simulation cache is retained."}
    };
    for(auto const& entry:entries) if(entry.first==label) return entry.second;
    return nullptr;
}
}
